// Types for the Emscripten module generated by build/build.sh (exports listed in build/CMakeLists.txt)
export type CloudiniModule = {
  HEAPU8: Uint8Array;
  _malloc(size: number): number;
  _free(ptr: number): void;
  /** Returns 0 on success, otherwise a pointer to an error message */
  _cldn_Decode(input: number, inputSize: number, output: number, outputCapacity: number): number;
  UTF8ToString(ptr: number): string;
};

export default function createCloudiniModule(options: {
  wasmBinary: ArrayBuffer;
}): Promise<CloudiniModule>;
